import{_ as o,o as a,c as t,a3 as s}from"./chunks/framework.DH50UWNB.js";const p=JSON.parse('{"title":"Tokens","description":"","frontmatter":{},"headers":[],"relativePath":"use/tokens.md","filePath":"use/tokens.md"}'),n={name:"use/tokens.md"};function r(i,e,c,h,k,d){return a(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="tokens" tabindex="-1">Tokens <a class="header-anchor" href="#tokens" aria-label="Permalink to &quot;Tokens&quot;">​</a></h1><p>A personal access token lets the <code>wake</code> CLI, a script or a CI pipeline act as you in one workspace.</p><p>Your coding agents use two ways in. Their Wake tools sign in to Wake&#39;s MCP server with OAuth, in the browser, without a token. Their hooks run the <code>wake</code> CLI, which uses the CLI&#39;s own token: the one <code>wake login</code> created on that machine.</p><h2 id="the-tokens-screen" tabindex="-1">The Tokens screen <a class="header-anchor" href="#the-tokens-screen" aria-label="Permalink to &quot;The Tokens screen&quot;">​</a></h2><p>Open <strong>Tokens</strong> in the header. It lists your tokens in the current workspace, each with its prefix, when it was created, when it expires and when it was last used. Revoked and expired tokens stay listed for 30 days.</p><p><code>wake login</code> creates a token named <code>wake CLI on &lt;machine&gt;</code> when you approve it in the browser, and it expires after 90 days, like any other; see <a href="/wake-dist/docs/start/cli#sign-in">Install the CLI and sign in</a>. When it expires, the CLI and your agents&#39; hooks ask you to run <code>wake login</code> again.</p><h2 id="create-a-token" tabindex="-1">Create a token <a class="header-anchor" href="#create-a-token" aria-label="Permalink to &quot;Create a token&quot;">​</a></h2><p>Enter a name, such as your machine&#39;s or your pipeline&#39;s, and choose <strong>Create token</strong>. Copy the secret at once: Wake shows it only once and keeps only its hash. A token expires after 90 days.</p><p>Viewers cannot create tokens in a workspace; see <a href="/wake-dist/docs/use/workspaces#roles">roles</a>.</p><p>To use it:</p><ul><li><code>wake login --with-token</code> asks for it without echoing it; see <a href="/wake-dist/docs/start/cli#sign-in-with-a-token">Sign in with a token</a>.</li><li>In CI, give it to the CLI as <code>WAKE_TOKEN</code>, with its server as <code>WAKE_SERVER</code>; see <a href="/wake-dist/docs/start/cli#in-ci">In CI</a>.</li><li>In your own scripts, see the <a href="/wake-dist/docs/reference/api">HTTP API</a>.</li></ul><h2 id="revoke-a-token" tabindex="-1">Revoke a token <a class="header-anchor" href="#revoke-a-token" aria-label="Permalink to &quot;Revoke a token&quot;">​</a></h2><p>Choose <strong>Revoke</strong> on its row and confirm. Anything that uses it stops working at once.</p><p>Wake also revokes tokens by itself when you leave a workspace, become a viewer, choose <a href="/wake-dist/docs/use/account#sign-out-everywhere">Sign out everywhere</a>, or when whoever runs the server disables your account. The <a href="/wake-dist/docs/use/audit-log">audit log</a> records each revoke with its cause.</p><p>Managing tokens needs the web app, or a browser session through the <a href="/wake-dist/docs/reference/api#tokens">HTTP API</a>, so a leaked token cannot create more tokens.</p>',15)])])}const w=o(n,[["render",r]]);export{p as __pageData,w as default};
